#include <iostream>
#include <string>

int main()
{
    std::string name{ "Aria" };
    int level{ 7 };
    double health{ 82.5 };
    char rank{ 'B' };
    bool isAlive{ true };

    std::cout << "Name: " << name << '\n';
    std::cout << "Level: " << level << '\n';
    std::cout << "Health: " << health << '\n';
    std::cout << "Rank: " << rank << '\n';
    std::cout << "Alive: " << isAlive << '\n';
    return 0;
}
